import{_ as t,c as o,b as r,o as n}from"./app-BRWvUhL_.js";const a={};function l(s,e){return n(),o("div",null,e[0]||(e[0]=[r('<p>The <a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multi-vendor Marketplace</a> app has come up with yet another connector add-on i.e. <strong>SooPOS Connector</strong>.</p><p>SooPOS [Shopify+POS] is a perfect Shopify POS inventory order management solution for online stores. <strong><a href="https://soopos.com/" target="_blank" rel="noopener noreferrer">Learn</a></strong></p><p>SooPOS connector helps to get the seller&#39;s products synced with the merchant&#39;s store if the seller&#39;s shop name will match the &quot;vendor&quot; field of the &quot;Add Product&quot; section of Shopify.</p><p>Moreover, if the merchant will edit those SooPOS products from Shopify end then, the changes will get updated automatically in the multivendor app.</p><p>You can enable the <strong>SooPOS connector</strong> from the “<strong>Feature App</strong>” section of the app.</p><p>Then, approve the additional charge of $10 USD/month over and above your current Multi-vendor app plan.</p><p>Let’s explore the connector in detail.</p><h3 id="required-conditions" tabindex="-1"><a class="header-anchor" href="#required-conditions"><span>Required Conditions</span></a></h3><p>The connector will work with newly added products, if the below three important conditions satisfy:</p><ol><li>The sellers need to enable the &quot;SooPOS Configuration&quot; from their respective seller panels.</li><li>SooPOS tag must be assigned to the SooPOS products.</li><li>The seller shop name on the marketplace should match the &quot;vendor&quot; field under the &quot;Add Product&quot; section of your Shopify store.</li></ol><h3 id="how-to-activate" tabindex="-1"><a class="header-anchor" href="#how-to-activate"><span>How to Activate?</span></a></h3><p>To enable this feature app, you need to visit the Feature app section and enable the SooPOS connector feature app. Click the <strong>Enable</strong> button to activate the feature app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Feature-Apps-Admin-1-1200x597.png" alt="Feature-Apps-Admin-1"></p><h3 id="workflow" tabindex="-1"><a class="header-anchor" href="#workflow"><span>WorkFlow</span></a></h3><p>After activating the feature app, the seller will get a new configuration added to their respective seller panels i.e. SooPOS Configuration.</p><h2 id="seller-end" tabindex="-1"><a class="header-anchor" href="#seller-end"><span><strong>SELLER END</strong></span></a></h2><p>The seller needs to log into their seller panel. Then, go to Configurations&gt;&gt;SooPOS Configurations.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Dashboard-Seller-•-Multivendor-MarketPlace-1200x597.png" alt="Dashboard-Seller-•-Multivendor-MarketPlace"></p><p>From here, Seller needs to enable the SooPOS option.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/sooPOS-Details-Seller-•-Multivendor-MarketPlace-1200x597.png" alt="sooPOS-Details-Seller-•-Multivendor-MarketPlace"></p><p>That&#39;s all required for sellers.</p><h2 id="admin-end" tabindex="-1"><a class="header-anchor" href="#admin-end"><span><strong>ADMIN END</strong></span></a></h2><p>Now, the merchant can import products with &quot;SooPOS Tag&quot; to the app, and then, the imported products will auto-assign to the sellers.</p><p><em><strong>Please Note: It will work on newly added products only. For Old products, the Merchant needs to manually assign the products to sellers.</strong></em></p><p><a href="https://webkul.com/blog/importing-products-from-shopify-to-multivendor-marketplace/" target="_blank" rel="noopener noreferrer"><strong>Learn How To Import Products from Shopify To App</strong></a></p><p><strong>Before You Import Products:-</strong></p><p>Make Sure the <strong>&quot;SooPOS&quot; Tag i</strong>s available on <strong>the products</strong> that you are going to import to the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/ravikant-store1-Products-Cup-Cake-Shopify-1200x597.png" alt="ravikant-store1-Products-Cup-Cake-Shopify"></p><p>Secondly, make sure that <strong>the seller shop name in the app should match the &quot;vendor&quot; name</strong> on Shopify.</p><p>Below screenshot shows the seller shop name on the multi-vendor app:-</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/Edit-Seller-Admin-1-1200x597.png" alt="Edit-Seller-Admin-1"></p><p>Below screenshot shows the &quot;Vendor&quot; field on Shopify end:-</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/09/ravikant-store1-Products-Cup-Cake-Shopify-1-1200x597.png" alt="ravikant-store1-Products-Cup-Cake-Shopify-1"></p><p>That&#39;s all you need to check before importing products.</p><p>Now, proceed to import products and the &quot;SooPOS&quot; products auto-assigned to the sellers in the app.</p>',35)]))}const i=t(a,[["render",l]]),h=JSON.parse('{"path":"/zenith/Featured-App/Connector/SOOPOS%20CONNECTOR.html","title":"SOOPOS CONNECTOR","lang":"en-US","frontmatter":{"title":"SOOPOS CONNECTOR","description":"SOOPOS CONNECTOR","date":"2025-07-25T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Required Conditions","slug":"required-conditions","link":"#required-conditions","children":[]},{"level":3,"title":"How to Activate?","slug":"how-to-activate","link":"#how-to-activate","children":[]},{"level":3,"title":"WorkFlow","slug":"workflow","link":"#workflow","children":[]},{"level":2,"title":"SELLER END","slug":"seller-end","link":"#seller-end","children":[]},{"level":2,"title":"ADMIN END","slug":"admin-end","link":"#admin-end","children":[]}],"git":{"updatedTime":1753692029000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"52c8b1d26d49bc54550dc3b20ce6d442bb390c03","time":1753692029000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"}]},"filePathRelative":"zenith/Featured-App/Connector/SOOPOS CONNECTOR.md"}');export{i as comp,h as data};
